# Builds the Llama prompt test for the Cloudflare connector (mcp__cloudflare__execute) from cloudflare/worker.js and
# state.json (made by getstate.mjs). Run from this folder: python3 llama-test-build.py > llama_code.js, then paste it.
import json,re
src=open('../../../cloudflare/worker.js',encoding='utf-8').read(); sysp=json.loads(re.search(r'const SYSTEM = (".*?");\n',src,re.S).group(1))
d=json.load(open('state.json'))
reqs=["keys what key is this song","yes","put those chords on my song","use the song's chords but keep the song's key, and the bass movement too","make bar 4 B minor","match this loop to my key","bar 2 ko F sharp 7 kar do","what key is my song in","give me another chord progression","copy the melody of this song too"]
TPL='async () => {\nconst SYSTEM = %s;\nconst ST = %s;\nconst INSTR = %s;\nconst REQS = %s;\nconst out = [];\nfor (const text of REQS) {\n  const st = JSON.parse(JSON.stringify(ST));\n  const history = [];\n  if (text === \'yes\') { st.offer = { keysAsked: \'Set your song to E minor at 124 BPM?\', ifUserSaysYes: [{ type: \'key\', key: \'E minor\', from: \'song\' }, { type: \'tempo\', bpm: 124 }] }; history.push({ role: \'user\', content: \'what key is this song\' }, { role: \'assistant\', content: "E minor at 124, I\'m fairly sure. It could be G major; the bass lands on E. Move your song to E minor at 124 BPM?" }); }\n  const ctx = \'Current song: \' + JSON.stringify(st).slice(0, 7000) + \'\\nInstruments you can use (id: name): \' + INSTR.slice(0, 4000);\n  const messages = [{ role: \'system\', content: SYSTEM }, ...history, { role: \'user\', content: ctx + \'\\n\\nThe user said: "\' + text + \'"\' }];\n  const t0 = Date.now();\n  try {\n    const r = await cloudflare.request({ method: \'POST\', path: \'/accounts/d9810812643ee32e2460689ca2ff73eb/ai/run/@cf/meta/llama-3.3-70b-instruct-fp8-fast\', body: { messages, max_tokens: 1800, temperature: 0.4, response_format: { type: \'json_schema\', json_schema: { type: \'object\', properties: { reply: { type: \'string\' }, actions: { type: \'array\', items: { type: \'object\' } } }, required: [\'reply\', \'actions\'] } } } });\n    const res = r.result || r; const raw = res.response !== undefined ? res.response : res;\n    out.push({ text, ms: Date.now() - t0, out: typeof raw === \'string\' ? raw.slice(0, 600) : raw });\n  } catch (e) { out.push({ text, err: String(e.message).slice(0, 300) }); }\n}\nreturn out;\n}'
print(TPL % (json.dumps(sysp,ensure_ascii=False), json.dumps(d['st'],ensure_ascii=False), json.dumps('; '.join(d['instruments']),ensure_ascii=False), json.dumps(reqs)))
